    24→// parseTranscript reads and parses a Claude Code transcript file.
    25→// Uses bufio.Reader to handle arbitrarily long lines.
    26→func parseTranscript(path string) ([]transcriptLine, error) {
    27→	file, err := os.Open(path) //nolint:gosec // Reading from controlled git metadata path
    28→	if err != nil {
    29→		return nil, err
    30→	}
    31→	defer func() { _ = file.Close() }()
    32→
    33→	var lines []transcriptLine
    34→	reader := bufio.NewReader(file)
    35→
    36→	for {
    37→		lineBytes, err := reader.ReadBytes('\n')
    38→		if err != nil && err != io.EOF {
    39→			return nil, fmt.Errorf("failed to read transcript: %w", err)
    40→		}
    41→
    42→		// Handle empty line or EOF without content
    43→		if len(lineBytes) == 0 {
    44→			if err == io.EOF {
    45→				break
    46→			}
    47→			continue
    48→		}
    49→
    50→		var line transcriptLine
    51→		if err := json.Unmarshal(lineBytes, &line); err == nil {
    52→			lines = append(lines, line)
    53→		}
    54→
    55→		if err == io.EOF {
    56→			break
    57→		}
    58→	}
    59→
    60→	return lines, nil
    61→}
