   252→// extractAssistantResponses collects all assistant text blocks from the given transcript slice.
   253→// A single prompt can trigger multiple assistant responses interspersed with tool calls.
   254→func extractAssistantResponses(transcript []transcriptLine) []string {
   255→	var texts []string
   256→	for _, line := range transcript {
   257→		if line.Type == transcriptTypeAssistant {
   258→			var msg assistantMessage
   259→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   260→				continue
   261→			}
   262→
   263→			for _, block := range msg.Content {
   264→				if block.Type == contentTypeText && block.Text != "" {
   265→					texts = append(texts, block.Text)
   266→				}
   267→			}
   268→		}
   269→	}
   270→	return texts
   271→}
   272→
   273→// extractUserPrompts extracts all user messages from the transcript in order.
   274→// Only considers messages with string content (not tool results).
   275→// IDE-injected context tags (like <ide_opened_file>) are stripped from the results.
   276→func extractUserPrompts(transcript []transcriptLine) []string {
   277→	var prompts []string
   278→	for i := range transcript {
   279→		if transcript[i].Type != transcriptTypeUser {
   280→			continue
   281→		}
   282→		var msg userMessage
   283→		if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   284→			continue
   285→		}
   286→
   287→		// Handle string content
   288→		if str, ok := msg.Content.(string); ok {
   289→			prompts = append(prompts, textutil.StripIDEContextTags(str))
   290→			continue
   291→		}
   292→
   293→		// Handle array content (only if it contains text blocks)
   294→		if arr, ok := msg.Content.([]interface{}); ok {
   295→			var texts []string
   296→			for _, item := range arr {
   297→				if m, ok := item.(map[string]interface{}); ok {
   298→					if m["type"] == contentTypeText {
   299→						if text, ok := m["text"].(string); ok {
   300→							texts = append(texts, text)
   301→						}
   302→					}
   303→				}
   304→			}
   305→			if len(texts) > 0 {
   306→				prompts = append(prompts, textutil.StripIDEContextTags(strings.Join(texts, "\n\n")))
   307→			}
   308→		}
   309→	}
   310→	return prompts
   311→}
   312→
   313→// extractLastUserPrompt extracts the last user message from the transcript.
   314→// Only considers messages with string content (not tool results).
   315→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   316→func extractLastUserPrompt(transcript []transcriptLine) string {
   317→	prompts := extractUserPrompts(transcript)
   318→	if len(prompts) == 0 {
   319→		return ""
   320→	}
   321→	return prompts[len(prompts)-1]
   322→}
   323→
   324→// extractLastAssistantMessage extracts the last text message from the assistant
   325→func extractLastAssistantMessage(transcript []transcriptLine) string {
   326→	for i := len(transcript) - 1; i >= 0; i-- {
   327→		if transcript[i].Type == transcriptTypeAssistant {
   328→			var msg assistantMessage
   329→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   330→				continue
   331→			}
   332→
   333→			for _, block := range msg.Content {
   334→				if block.Type == contentTypeText && block.Text != "" {
   335→					return block.Text
   336→				}
   337→			}
   338→		}
   339→	}
   340→	return ""
   341→}
   342→
   343→// findLastUserUUID finds the UUID of the last user message (that has string content)
   344→func findLastUserUUID(transcript []transcriptLine) string {
   345→	for i := len(transcript) - 1; i >= 0; i-- {
   346→		if transcript[i].Type == transcriptTypeUser {
   347→			var msg userMessage
   348→			if err := json.Unmarshal(transcript[i].Message, &msg); err != nil {
   349→				continue
   350→			}
   351→			// Only count messages with string content (not tool results)
   352→			if _, ok := msg.Content.(string); ok {
   353→				return transcript[i].UUID
   354→			}
   355→		}
   356→	}
   357→	return ""
   358→}
   359→
   360→// filterTranscriptAfterUUID returns transcript lines after the given UUID
   361→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   362→	if uuid == "" {
   363→		return transcript
   364→	}
   365→
   366→	foundIndex := -1
   367→	for i, line := range transcript {
   368→		if line.UUID == uuid {
   369→			foundIndex = i
   370→			break
   371→		}
   372→	}
   373→
   374→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
   375→		return transcript
   376→	}
   377→
   378→	return transcript[foundIndex+1:]
   379→}
