// CalculateTotalTokenUsage calculates token usage for a turn, including subagents.
// It parses the main transcript from startLine, extracts spawned agent IDs,
// and calculates tokens for each subagent transcript.
func CalculateTotalTokenUsage(transcriptPath string, startLine int, subagentsDir string) (*TokenUsage, error) {
	// Calculate main transcript tokens
	mainUsage, err := CalculateTokenUsageFromFile(transcriptPath, startLine)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate main transcript tokens: %w", err)
	}

	// Parse transcript to find spawned agents
	transcript, _, err := parseTranscriptFromLine(transcriptPath, startLine)
	if err != nil {
		return nil, fmt.Errorf("failed to parse transcript for agent extraction: %w", err)
	}

	agentIDs := ExtractSpawnedAgentIDs(transcript)
	if len(agentIDs) == 0 {
		return mainUsage, nil
	}

	// Calculate subagent tokens
	subagentUsage := &TokenUsage{}
	for agentID := range agentIDs {
		agentPath := filepath.Join(subagentsDir, fmt.Sprintf("agent-%s.jsonl", agentID))
		agentUsage, err := CalculateTokenUsageFromFile(agentPath, 0)
		if err != nil {
			// Log warning but continue - agent file might not exist
			continue
		}
		subagentUsage.Add(agentUsage)
	}

	if subagentUsage.APICallCount > 0 {
		mainUsage.SubagentTokens = subagentUsage
	}

	return mainUsage, nil
}

