// messageUsage represents token usage from a Claude API response
type messageUsage struct {
	InputTokens              int `json:"input_tokens"`
	CacheCreationInputTokens int `json:"cache_creation_input_tokens"`
	CacheReadInputTokens     int `json:"cache_read_input_tokens"`
	OutputTokens             int `json:"output_tokens"`
}

// messageWithUsage represents an assistant message with usage data
type messageWithUsage struct {
	ID    string       `json:"id"`
	Usage messageUsage `json:"usage"`
}

// TokenUsage represents aggregated token usage for a checkpoint
type TokenUsage struct {
	// Input tokens (fresh, not from cache)
	InputTokens int `json:"input_tokens"`
	// Tokens written to cache (billable at cache write rate)
	CacheCreationTokens int `json:"cache_creation_tokens"`
	// Tokens read from cache (discounted rate)
	CacheReadTokens int `json:"cache_read_tokens"`
	// Output tokens generated
	OutputTokens int `json:"output_tokens"`
	// Number of API calls made
	APICallCount int `json:"api_call_count"`
	// Subagent token usage (if any agents were spawned)
	SubagentTokens *TokenUsage `json:"subagent_tokens,omitempty"`
}

// Total returns the total tokens (input + cache_write + cache_read + output)
func (t *TokenUsage) Total() int {
	return t.InputTokens + t.CacheCreationTokens + t.CacheReadTokens + t.OutputTokens
}

// Billable returns an approximation of billable tokens (excludes cache reads which are discounted)
func (t *TokenUsage) Billable() int {
	return t.InputTokens + t.CacheCreationTokens + t.OutputTokens
}

// Add adds another TokenUsage to this one
func (t *TokenUsage) Add(other *TokenUsage) {
	if other == nil {
		return
	}
	t.InputTokens += other.InputTokens
	t.CacheCreationTokens += other.CacheCreationTokens
	t.CacheReadTokens += other.CacheReadTokens
	t.OutputTokens += other.OutputTokens
	t.APICallCount += other.APICallCount
}

