   611→// CalculateTokenUsage calculates token usage from a transcript.
   612→// Due to streaming, multiple transcript rows may share the same message.id.
   613→// We deduplicate by taking the row with the highest output_tokens for each message.id.
   614→func CalculateTokenUsage(transcript []transcriptLine) *checkpoint.TokenUsage {
   615→	// Map from message.id to the usage with highest output_tokens
   616→	usageByMessageID := make(map[string]messageUsage)
   617→
   618→	for _, line := range transcript {
   619→		if line.Type != transcriptTypeAssistant {
   620→			continue
   621→		}
   622→
   623→		var msg messageWithUsage
   624→		if err := json.Unmarshal(line.Message, &msg); err != nil {
   625→			continue
   626→		}
   627→
   628→		if msg.ID == "" {
   629→			continue
   630→		}
   631→
   632→		// Keep the entry with highest output_tokens (final streaming state)
   633→		existing, exists := usageByMessageID[msg.ID]
   634→		if !exists || msg.Usage.OutputTokens > existing.OutputTokens {
   635→			usageByMessageID[msg.ID] = msg.Usage
   636→		}
   637→	}
   638→
   639→	// Sum up all unique messages
   640→	usage := &checkpoint.TokenUsage{
   641→		APICallCount: len(usageByMessageID),
   642→	}
   643→	for _, u := range usageByMessageID {
   644→		usage.InputTokens += u.InputTokens
   645→		usage.CacheCreationTokens += u.CacheCreationInputTokens
   646→		usage.CacheReadTokens += u.CacheReadInputTokens
   647→		usage.OutputTokens += u.OutputTokens
   648→	}
   649→
   650→	return usage
   651→}
