   653→// CalculateTokenUsageFromFile calculates token usage from a transcript file.
   654→// If startLine > 0, only considers lines from startLine onwards.
   655→func CalculateTokenUsageFromFile(path string, startLine int) (*checkpoint.TokenUsage, error) {
   656→	if path == "" {
   657→		return &checkpoint.TokenUsage{}, nil
   658→	}
   659→
   660→	transcript, _, err := parseTranscriptFromLine(path, startLine)
   661→	if err != nil {
   662→		return nil, err
   663→	}
   664→
   665→	return CalculateTokenUsage(transcript), nil
   666→}
