   169→			// Only count messages with string content (real user prompts)
   170→			if _, ok := msg.Content.(string); ok {
   171→				userIndices = append(userIndices, i)
   172→			} else if arr, ok := msg.Content.([]interface{}); ok {
   173→				// Check if array has text blocks (also a real user prompt)
   174→				for _, item := range arr {
   175→					if m, ok := item.(map[string]interface{}); ok {
   176→						if m["type"] == contentTypeText {
   177→							userIndices = append(userIndices, i)
   178→							break
   179→						}
   180→					}
   181→				}
   182→			}
   183→		}
   184→	}
